-- Philippine payroll preparation, immutable approvals, private payslips, and ledger posting.
create function private.payroll_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='payroll');$$;

create table public.statutory_rule_sets(
 id uuid primary key default gen_random_uuid(),agency text not null check(agency in('BIR','SSS','PHILHEALTH','PAGIBIG','DOLE')),code text not null,version integer not null check(version>0),effective_from date not null,effective_to date,
 configuration jsonb not null check(jsonb_typeof(configuration)='object'),source_reference text not null,legally_reviewed boolean not null default false,created_at timestamptz not null default now(),unique(agency,code,version),check(effective_to is null or effective_to>=effective_from)
);
insert into public.statutory_rule_sets(agency,code,version,effective_from,configuration,source_reference,legally_reviewed)values
 ('SSS','EMPLOYED',1,date'2025-01-01','{"employeeRate":0.05,"employerRate":0.10,"minimumMsc":5000,"maximumMsc":35000,"ecLow":10,"ecHigh":30,"ecThreshold":15000}','SSS contribution schedule effective January 2025',false),
 ('PHILHEALTH','EMPLOYED',1,date'2025-01-01','{"totalRate":0.05,"employeeShare":0.5,"employerShare":0.5,"salaryFloor":10000,"salaryCeiling":100000}','PhilHealth employer premium table; effective date requires release review',false),
 ('PAGIBIG','EMPLOYED',1,date'2024-02-01','{"employeeRate":0.02,"employerRate":0.02,"compensationCeiling":5000}','Pag-IBIG mandatory savings baseline; requires release review',false),
 ('DOLE','PREMIUMS',1,date'2024-01-01','{"overtimeMultiplier":1.25,"restDayMultiplier":1.30,"nightDifferential":0.10,"regularHolidayWorked":2.0,"specialHolidayWorked":1.30}','DOLE statutory monetary benefits baseline',false),
 ('BIR','WITHHOLDING_COMPENSATION',1,date'2023-01-01','{"monthlyBrackets":[{"over":0,"base":0,"rate":0},{"over":20833,"base":0,"rate":0.15},{"over":33333,"base":1875,"rate":0.20},{"over":66667,"base":8541.8,"rate":0.25},{"over":166667,"base":33541.8,"rate":0.30},{"over":666667,"base":183541.8,"rate":0.35}]}','BIR withholding table effective 2023 onward',false)
on conflict(agency,code,version)do nothing;

create table public.employee_compensation_profiles(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,employee_id uuid not null,branch_id uuid not null,effective_from date not null,effective_to date,
 employment_type text not null check(employment_type in('regular','probationary','contractual','part_time')),salary_basis text not null check(salary_basis in('monthly','daily','hourly')),base_rate numeric(18,4)not null check(base_rate>0),
 pay_frequency text not null check(pay_frequency in('weekly','semi_monthly','monthly')),work_days_per_week numeric(4,2)not null default 6 check(work_days_per_week>0 and work_days_per_week<=7),hours_per_day numeric(4,2)not null default 8 check(hours_per_day>0 and hours_per_day<=24),rest_day integer not null default 0 check(rest_day between 0 and 6),
 tax_status text not null default'withholding'check(tax_status in('withholding','minimum_wage_exempt','exempt')),region_code text not null default'NCR',deduction_schedule text not null default'every_run'check(deduction_schedule in('every_run','month_end')),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),foreign key(employee_id,organization_id)references public.employees(id,organization_id)on delete restrict,foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,check(effective_to is null or effective_to>=effective_from)
);
create unique index employee_compensation_current_idx on public.employee_compensation_profiles(employee_id)where effective_to is null;
create table public.employee_sensitive_identifiers(
 employee_id uuid primary key,organization_id uuid not null,sss_ciphertext text,sss_last_four text,philhealth_ciphertext text,philhealth_last_four text,pagibig_ciphertext text,pagibig_last_four text,tin_ciphertext text,tin_last_four text,key_version integer not null default 1,
 updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),foreign key(employee_id,organization_id)references public.employees(id,organization_id)on delete cascade,
 check((sss_ciphertext is null and sss_last_four is null)or(char_length(sss_ciphertext)>=24 and sss_last_four~'^[A-Za-z0-9]{4}$')),check((philhealth_ciphertext is null and philhealth_last_four is null)or(char_length(philhealth_ciphertext)>=24 and philhealth_last_four~'^[A-Za-z0-9]{4}$')),check((pagibig_ciphertext is null and pagibig_last_four is null)or(char_length(pagibig_ciphertext)>=24 and pagibig_last_four~'^[A-Za-z0-9]{4}$')),check((tin_ciphertext is null and tin_last_four is null)or(char_length(tin_ciphertext)>=24 and tin_last_four~'^[A-Za-z0-9]{4}$'))
);
create table public.payroll_adjustments(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,employee_id uuid not null,period_start date not null,period_end date not null,component_type text not null check(component_type in('allowance','commission','bonus','loan','deduction','absence','thirteenth_month','retroactive')),description text not null,amount numeric(18,4)not null check(amount>0),taxable boolean not null default true,status text not null default'approved'check(status in('draft','approved','applied','cancelled')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),foreign key(employee_id,organization_id)references public.employees(id,organization_id)on delete restrict,check(period_end>=period_start)
);
create table public.employee_loans(id uuid primary key default gen_random_uuid(),organization_id uuid not null,employee_id uuid not null,lender text not null,reference text,original_amount numeric(18,4)not null check(original_amount>0),balance numeric(18,4)not null check(balance>=0),installment_amount numeric(18,4)not null check(installment_amount>0),starts_on date not null,status text not null default'active'check(status in('active','paid','cancelled')),created_at timestamptz not null default now(),unique(id,organization_id),foreign key(employee_id,organization_id)references public.employees(id,organization_id)on delete restrict);
create table public.payroll_runs(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,branch_id uuid,period_start date not null,period_end date not null,pay_date date not null,pay_frequency text not null check(pay_frequency in('weekly','semi_monthly','monthly')),run_type text not null default'regular'check(run_type in('regular','adjustment')),status text not null default'draft'check(status in('draft','calculated','approved','posted','cancelled')),idempotency_key text not null,rule_snapshot jsonb not null default'{}',exception_count integer not null default 0,total_gross numeric(18,4)not null default 0,total_deductions numeric(18,4)not null default 0,total_net numeric(18,4)not null default 0,total_employer_contributions numeric(18,4)not null default 0,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),calculated_at timestamptz,approved_at timestamptz,approved_by uuid references auth.users(id),journal_entry_id uuid,unique(id,organization_id),unique(organization_id,idempotency_key),foreign key(branch_id,organization_id)references public.branches(id,organization_id),foreign key(journal_entry_id,organization_id)references public.journal_entries(id,organization_id),check(period_end>=period_start)
);
create table public.payroll_results(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,run_id uuid not null,employee_id uuid not null,compensation_profile_id uuid not null,regular_pay numeric(18,4)not null default 0,overtime_pay numeric(18,4)not null default 0,other_earnings numeric(18,4)not null default 0,gross_pay numeric(18,4)not null,withholding_tax numeric(18,4)not null default 0,sss_employee numeric(18,4)not null default 0,sss_employer numeric(18,4)not null default 0,philhealth_employee numeric(18,4)not null default 0,philhealth_employer numeric(18,4)not null default 0,pagibig_employee numeric(18,4)not null default 0,pagibig_employer numeric(18,4)not null default 0,other_deductions numeric(18,4)not null default 0,net_pay numeric(18,4)not null,calculation_snapshot jsonb not null,created_at timestamptz not null default now(),unique(id,organization_id),unique(run_id,employee_id),foreign key(run_id,organization_id)references public.payroll_runs(id,organization_id)on delete restrict,foreign key(employee_id,organization_id)references public.employees(id,organization_id),foreign key(compensation_profile_id,organization_id)references public.employee_compensation_profiles(id,organization_id)
);
create table public.payroll_components(id uuid primary key default gen_random_uuid(),organization_id uuid not null,payroll_result_id uuid not null,component_type text not null check(component_type in('earning','deduction','employer_contribution')),code text not null,description text not null,amount numeric(18,4)not null check(amount>=0),taxable boolean not null default false,source_type text,source_id uuid,created_at timestamptz not null default now(),foreign key(payroll_result_id,organization_id)references public.payroll_results(id,organization_id)on delete restrict);
create table public.payslips(id uuid primary key default gen_random_uuid(),organization_id uuid not null,run_id uuid not null,payroll_result_id uuid not null,employee_id uuid not null,payslip_number text not null,snapshot jsonb not null,checksum text not null,created_at timestamptz not null default now(),unique(id,organization_id),unique(run_id,employee_id),unique(organization_id,payslip_number),foreign key(run_id,organization_id)references public.payroll_runs(id,organization_id),foreign key(payroll_result_id,organization_id)references public.payroll_results(id,organization_id),foreign key(employee_id,organization_id)references public.employees(id,organization_id));
create table public.payroll_exceptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,run_id uuid not null,employee_id uuid,code text not null,severity text not null check(severity in('warning','blocking')),message text not null,status text not null default'open'check(status in('open','resolved','accepted')),created_at timestamptz not null default now(),unique(run_id,employee_id,code),foreign key(run_id,organization_id)references public.payroll_runs(id,organization_id)on delete cascade,foreign key(employee_id,organization_id)references public.employees(id,organization_id));
create index compensation_profiles_effective_idx on public.employee_compensation_profiles(organization_id,branch_id,effective_from);create index payroll_runs_period_idx on public.payroll_runs(organization_id,period_end,status);create index payroll_results_run_idx on public.payroll_results(run_id,employee_id);create index payslips_employee_idx on public.payslips(employee_id,created_at desc);create index payroll_exceptions_open_idx on public.payroll_exceptions(run_id)where status='open';

create function private.reject_approved_payroll_mutation()returns trigger language plpgsql set search_path='' as $$begin if tg_op='DELETE'or old.status in('approved','posted')then raise exception'Approved payroll is immutable.'using errcode='42501';end if;return new;end;$$;create trigger payroll_runs_immutable before update or delete on public.payroll_runs for each row execute function private.reject_approved_payroll_mutation();
create function private.reject_payroll_result_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception'Payroll results are immutable; use an adjustment run.'using errcode='42501';end;$$;create trigger payroll_results_immutable before update or delete on public.payroll_results for each row execute function private.reject_payroll_result_mutation();create trigger payroll_components_immutable before update or delete on public.payroll_components for each row execute function private.reject_payroll_result_mutation();create trigger payslips_immutable before update or delete on public.payslips for each row execute function private.reject_payroll_result_mutation();

create function private.monthly_withholding(requested_taxable numeric)returns numeric language plpgsql immutable set search_path='' as $$begin return round(case when requested_taxable<=20833 then 0 when requested_taxable<=33333 then(requested_taxable-20833)*.15 when requested_taxable<=66667 then 1875+(requested_taxable-33333)*.20 when requested_taxable<=166667 then 8541.8+(requested_taxable-66667)*.25 when requested_taxable<=666667 then 33541.8+(requested_taxable-166667)*.30 else 183541.8+(requested_taxable-666667)*.35 end,4);end;$$;
create function private.pay_period_divisor(requested_frequency text)returns numeric language sql immutable set search_path='' as $$select case requested_frequency when'weekly'then 52.0/12.0 when'semi_monthly'then 2 else 1 end;$$;

create function public.save_employee_compensation(requested_organization_id uuid,requested_employee_id uuid,requested_branch_id uuid,requested_effective_from date,requested_employment_type text,requested_salary_basis text,requested_base_rate numeric,requested_pay_frequency text,requested_work_days numeric,requested_hours numeric,requested_rest_day integer,requested_tax_status text,requested_region_code text,requested_deduction_schedule text)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());target_id uuid;begin if actor is null or not private.payroll_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'payroll.manage',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_employment_type not in('regular','probationary','contractual','part_time')or requested_salary_basis not in('monthly','daily','hourly')or requested_base_rate<=0 or requested_pay_frequency not in('weekly','semi_monthly','monthly')or requested_tax_status not in('withholding','minimum_wage_exempt','exempt')then raise exception'Invalid compensation profile.'using errcode='22023';end if;update public.employee_compensation_profiles set effective_to=requested_effective_from-1 where employee_id=requested_employee_id and effective_to is null and effective_from<requested_effective_from;insert into public.employee_compensation_profiles(organization_id,employee_id,branch_id,effective_from,employment_type,salary_basis,base_rate,pay_frequency,work_days_per_week,hours_per_day,rest_day,tax_status,region_code,deduction_schedule,created_by)values(requested_organization_id,requested_employee_id,requested_branch_id,requested_effective_from,requested_employment_type,requested_salary_basis,requested_base_rate,requested_pay_frequency,requested_work_days,requested_hours,requested_rest_day,requested_tax_status,upper(requested_region_code),requested_deduction_schedule,actor)returning id into target_id;return target_id;end;$$;

create function public.save_employee_sensitive_identifiers(requested_organization_id uuid,requested_employee_id uuid,requested_sss_ciphertext text,requested_sss_last_four text,requested_philhealth_ciphertext text,requested_philhealth_last_four text,requested_pagibig_ciphertext text,requested_pagibig_last_four text,requested_tin_ciphertext text,requested_tin_last_four text,requested_key_version integer)returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());branch uuid;begin select branch_id into branch from public.employees where id=requested_employee_id and organization_id=requested_organization_id;if actor is null or branch is null or not private.payroll_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'payroll.sensitive',branch)then raise exception'Permission denied.'using errcode='42501';end if;insert into public.employee_sensitive_identifiers(employee_id,organization_id,sss_ciphertext,sss_last_four,philhealth_ciphertext,philhealth_last_four,pagibig_ciphertext,pagibig_last_four,tin_ciphertext,tin_last_four,key_version,updated_by)values(requested_employee_id,requested_organization_id,requested_sss_ciphertext,requested_sss_last_four,requested_philhealth_ciphertext,requested_philhealth_last_four,requested_pagibig_ciphertext,requested_pagibig_last_four,requested_tin_ciphertext,requested_tin_last_four,requested_key_version,actor)on conflict(employee_id)do update set sss_ciphertext=excluded.sss_ciphertext,sss_last_four=excluded.sss_last_four,philhealth_ciphertext=excluded.philhealth_ciphertext,philhealth_last_four=excluded.philhealth_last_four,pagibig_ciphertext=excluded.pagibig_ciphertext,pagibig_last_four=excluded.pagibig_last_four,tin_ciphertext=excluded.tin_ciphertext,tin_last_four=excluded.tin_last_four,key_version=excluded.key_version,updated_by=actor,updated_at=now();end;$$;
create function public.masked_employee_identifiers(requested_organization_id uuid,requested_employee_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare actor uuid:=(select auth.uid());branch uuid;result jsonb;begin select branch_id into branch from public.employees where id=requested_employee_id and organization_id=requested_organization_id;if actor is null or branch is null or not private.can_business_permission(requested_organization_id,'payroll.sensitive',branch)then raise exception'Permission denied.'using errcode='42501';end if;select jsonb_build_object('sss',case when sss_last_four is null then null else'••••'||sss_last_four end,'philHealth',case when philhealth_last_four is null then null else'••••'||philhealth_last_four end,'pagIbig',case when pagibig_last_four is null then null else'••••'||pagibig_last_four end,'tin',case when tin_last_four is null then null else'••••'||tin_last_four end,'keyVersion',key_version)into result from public.employee_sensitive_identifiers where employee_id=requested_employee_id and organization_id=requested_organization_id;return coalesce(result,'{}');end;$$;

create function public.calculate_payroll_run(requested_organization_id uuid,requested_branch_id uuid,requested_period_start date,requested_period_end date,requested_pay_date date,requested_frequency text,requested_run_type text,requested_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());target_id uuid;profile public.employee_compensation_profiles%rowtype;employee_row public.employees%rowtype;regular_minutes numeric;overtime_minutes numeric;days_present numeric;divisor numeric;hourly_rate numeric;regular_value numeric;overtime_value numeric;earnings_value numeric;deductions_value numeric;gross_value numeric;monthly_equivalent numeric;sss_employee_value numeric;sss_employer_value numeric;phil_employee_value numeric;phil_employer_value numeric;pagibig_employee_value numeric;pagibig_employer_value numeric;withholding_value numeric;net_value numeric;result_id uuid;rules jsonb;run_gross numeric:=0;run_deductions numeric:=0;run_net numeric:=0;run_employer numeric:=0;begin
 select id into target_id from public.payroll_runs where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return target_id;end if;if actor is null or not private.payroll_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'payroll.manage',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_period_end<requested_period_start or requested_pay_date<requested_period_end or requested_frequency not in('weekly','semi_monthly','monthly')or requested_run_type not in('regular','adjustment')or char_length(btrim(requested_idempotency_key))not between 8 and 200 then raise exception'Invalid payroll run.'using errcode='22023';end if;
 select jsonb_object_agg(agency||':'||code,jsonb_build_object('id',id,'version',version,'effectiveFrom',effective_from,'configuration',configuration,'sourceReference',source_reference))into rules from public.statutory_rule_sets where effective_from<=requested_period_end and(effective_to is null or effective_to>=requested_period_start);
 insert into public.payroll_runs(organization_id,branch_id,period_start,period_end,pay_date,pay_frequency,run_type,status,idempotency_key,rule_snapshot,created_by)values(requested_organization_id,requested_branch_id,requested_period_start,requested_period_end,requested_pay_date,requested_frequency,requested_run_type,'draft',requested_idempotency_key,coalesce(rules,'{}'),actor)returning id into target_id;
 for profile in select*from public.employee_compensation_profiles where organization_id=requested_organization_id and(requested_branch_id is null or branch_id=requested_branch_id)and pay_frequency=requested_frequency and effective_from<=requested_period_end and(effective_to is null or effective_to>=requested_period_start)order by employee_id loop
  select*into employee_row from public.employees where id=profile.employee_id and organization_id=requested_organization_id and employment_status in('active','on_leave');if employee_row.id is null then continue;end if;
  select coalesce(sum(regular_minutes),0),coalesce(sum(overtime_minutes),0),count(*)filter(where status='closed')into regular_minutes,overtime_minutes,days_present from public.attendance_sessions where organization_id=requested_organization_id and employee_id=profile.employee_id and work_date between requested_period_start and requested_period_end and status='closed';
  divisor:=private.pay_period_divisor(profile.pay_frequency);hourly_rate:=case profile.salary_basis when'monthly'then profile.base_rate/(profile.work_days_per_week*52/12*profile.hours_per_day)when'daily'then profile.base_rate/profile.hours_per_day else profile.base_rate end;
  regular_value:=round(case profile.salary_basis when'monthly'then profile.base_rate/divisor when'daily'then days_present*profile.base_rate else regular_minutes/60*hourly_rate end,4);overtime_value:=round(overtime_minutes/60*hourly_rate*1.25,4);
  select coalesce(sum(amount)filter(where component_type in('allowance','commission','bonus','thirteenth_month','retroactive')),0),coalesce(sum(amount)filter(where component_type in('loan','deduction','absence')),0)into earnings_value,deductions_value from public.payroll_adjustments where organization_id=requested_organization_id and employee_id=profile.employee_id and status='approved'and period_start<=requested_period_end and period_end>=requested_period_start;
  gross_value:=round(regular_value+overtime_value+earnings_value,4);monthly_equivalent:=gross_value*divisor;sss_employee_value:=round(least(greatest(monthly_equivalent,5000),35000)*.05/divisor,4);sss_employer_value:=round(least(greatest(monthly_equivalent,5000),35000)*.10/divisor,4);phil_employee_value:=round(least(greatest(monthly_equivalent,10000),100000)*.025/divisor,4);phil_employer_value:=phil_employee_value;pagibig_employee_value:=round(least(monthly_equivalent,5000)*.02/divisor,4);pagibig_employer_value:=pagibig_employee_value;withholding_value:=case when profile.tax_status='withholding'then round(private.monthly_withholding(greatest(0,monthly_equivalent-sss_employee_value*divisor-phil_employee_value*divisor-pagibig_employee_value*divisor))/divisor,4)else 0 end;net_value:=round(gross_value-sss_employee_value-phil_employee_value-pagibig_employee_value-withholding_value-deductions_value,4);
  if net_value<0 then insert into public.payroll_exceptions(organization_id,run_id,employee_id,code,severity,message)values(requested_organization_id,target_id,profile.employee_id,'NEGATIVE_NET_PAY','blocking','Deductions exceed employee earnings.');end if;
  insert into public.payroll_results(organization_id,run_id,employee_id,compensation_profile_id,regular_pay,overtime_pay,other_earnings,gross_pay,withholding_tax,sss_employee,sss_employer,philhealth_employee,philhealth_employer,pagibig_employee,pagibig_employer,other_deductions,net_pay,calculation_snapshot)values(requested_organization_id,target_id,profile.employee_id,profile.id,regular_value,overtime_value,earnings_value,gross_value,withholding_value,sss_employee_value,sss_employer_value,phil_employee_value,phil_employer_value,pagibig_employee_value,pagibig_employer_value,deductions_value,net_value,jsonb_build_object('regularMinutes',regular_minutes,'overtimeMinutes',overtime_minutes,'daysPresent',days_present,'hourlyRate',hourly_rate,'monthlyEquivalent',monthly_equivalent,'ruleSnapshot',rules))returning id into result_id;
  insert into public.payroll_components(organization_id,payroll_result_id,component_type,code,description,amount,taxable)values(requested_organization_id,result_id,'earning','REGULAR','Regular pay',regular_value,true),(requested_organization_id,result_id,'earning','OVERTIME','Overtime pay',overtime_value,true),(requested_organization_id,result_id,'earning','OTHER','Allowances, commissions, and bonuses',earnings_value,true),(requested_organization_id,result_id,'deduction','WHT','Withholding tax',withholding_value,false),(requested_organization_id,result_id,'deduction','SSS-EE','SSS employee share',sss_employee_value,false),(requested_organization_id,result_id,'deduction','PHIC-EE','PhilHealth employee share',phil_employee_value,false),(requested_organization_id,result_id,'deduction','HDMF-EE','Pag-IBIG employee share',pagibig_employee_value,false),(requested_organization_id,result_id,'deduction','OTHER-DED','Loans and other deductions',deductions_value,false),(requested_organization_id,result_id,'employer_contribution','SSS-ER','SSS employer share',sss_employer_value,false),(requested_organization_id,result_id,'employer_contribution','PHIC-ER','PhilHealth employer share',phil_employer_value,false),(requested_organization_id,result_id,'employer_contribution','HDMF-ER','Pag-IBIG employer share',pagibig_employer_value,false);
  run_gross:=run_gross+gross_value;run_deductions:=run_deductions+gross_value-net_value;run_net:=run_net+net_value;run_employer:=run_employer+sss_employer_value+phil_employer_value+pagibig_employer_value;
 end loop;
 update public.payroll_runs set status='calculated',exception_count=(select count(*)from public.payroll_exceptions where run_id=target_id and status='open'),total_gross=run_gross,total_deductions=run_deductions,total_net=run_net,total_employer_contributions=run_employer,calculated_at=now()where id=target_id;return target_id;
end;$$;

create function public.approve_payroll_run(requested_organization_id uuid,requested_run_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());run_row public.payroll_runs%rowtype;result_row public.payroll_results%rowtype;employee_row public.employees%rowtype;number_value text;snapshot_value jsonb;checksum_value text;lines jsonb;entry_id uuid;sss_total numeric;phil_total numeric;pagibig_total numeric;withholding_total numeric;other_deduction_total numeric;begin select*into run_row from public.payroll_runs where id=requested_run_id and organization_id=requested_organization_id for update;if actor is null or run_row.id is null or not private.payroll_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'payroll.approve',run_row.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if run_row.status<>'calculated'or exists(select 1 from public.payroll_exceptions where run_id=run_row.id and severity='blocking'and status='open')then raise exception'Payroll is not ready for approval.'using errcode='P0001';end if;
 select coalesce(sum(sss_employee+sss_employer),0),coalesce(sum(philhealth_employee+philhealth_employer),0),coalesce(sum(pagibig_employee+pagibig_employer),0),coalesce(sum(withholding_tax),0),coalesce(sum(other_deductions),0)into sss_total,phil_total,pagibig_total,withholding_total,other_deduction_total from public.payroll_results where run_id=run_row.id;
 lines:=jsonb_build_array(jsonb_build_object('accountKey','salary_expense','debit',run_row.total_gross,'credit',0),jsonb_build_object('accountKey','employer_contribution_expense','debit',run_row.total_employer_contributions,'credit',0),jsonb_build_object('accountKey','payroll_payable','debit',0,'credit',run_row.total_net),jsonb_build_object('accountKey','withholding_payable','debit',0,'credit',withholding_total),jsonb_build_object('accountKey','sss_payable','debit',0,'credit',sss_total),jsonb_build_object('accountKey','philhealth_payable','debit',0,'credit',phil_total),jsonb_build_object('accountKey','pagibig_payable','debit',0,'credit',pagibig_total),jsonb_build_object('accountKey','employee_deductions_payable','debit',0,'credit',other_deduction_total));
 entry_id:=private.post_journal(requested_organization_id,run_row.branch_id,run_row.pay_date,'payroll',run_row.id,'payroll:approved:'||run_row.id,'Approved payroll',lines,actor);
 for result_row in select*from public.payroll_results where run_id=run_row.id order by employee_id loop select*into employee_row from public.employees where id=result_row.employee_id;number_value:='PAY-'||to_char(run_row.pay_date,'YYYYMMDD')||'-'||employee_row.employee_number;snapshot_value:=jsonb_build_object('payslipNumber',number_value,'employee',jsonb_build_object('id',employee_row.id,'number',employee_row.employee_number,'name',employee_row.name,'position',employee_row.position),'period',jsonb_build_object('start',run_row.period_start,'end',run_row.period_end,'payDate',run_row.pay_date),'earnings',jsonb_build_object('regular',result_row.regular_pay,'overtime',result_row.overtime_pay,'other',result_row.other_earnings,'gross',result_row.gross_pay),'deductions',jsonb_build_object('withholdingTax',result_row.withholding_tax,'sss',result_row.sss_employee,'philHealth',result_row.philhealth_employee,'pagIbig',result_row.pagibig_employee,'other',result_row.other_deductions),'netPay',result_row.net_pay,'ruleSnapshot',run_row.rule_snapshot);checksum_value:=encode(extensions.digest(snapshot_value::text,'sha256'),'hex');insert into public.payslips(organization_id,run_id,payroll_result_id,employee_id,payslip_number,snapshot,checksum)values(requested_organization_id,run_row.id,result_row.id,result_row.employee_id,number_value,snapshot_value,checksum_value);end loop;
 perform set_config('app.payroll_approval','on',true);update public.payroll_runs set status='posted',approved_at=now(),approved_by=actor,journal_entry_id=entry_id where id=run_row.id;perform set_config('app.payroll_approval','off',true);update public.attendance_sessions set payroll_status='exported',payroll_reference=run_row.id::text,exported_at=now()where organization_id=requested_organization_id and(requested_run_id is not null)and work_date between run_row.period_start and run_row.period_end and(run_row.branch_id is null or branch_id=run_row.branch_id)and status='closed';return entry_id;end;$$;

create or replace function private.reject_approved_payroll_mutation()returns trigger language plpgsql set search_path='' as $$begin if(tg_op='DELETE'or old.status in('approved','posted'))and coalesce(current_setting('app.payroll_approval',true),'off')<>'on'then raise exception'Approved payroll is immutable.'using errcode='42501';end if;return new;end;$$;

create function public.payroll_dashboard(requested_organization_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if(select auth.uid())is null or not private.payroll_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'payroll.read',null)then raise exception'Permission denied.'using errcode='42501';end if;select jsonb_build_object('configuredEmployees',(select count(*)from public.employee_compensation_profiles where organization_id=requested_organization_id and effective_to is null),'calculatedRuns',(select count(*)from public.payroll_runs where organization_id=requested_organization_id and status='calculated'),'postedRuns',(select count(*)from public.payroll_runs where organization_id=requested_organization_id and status='posted'),'blockingExceptions',(select count(*)from public.payroll_exceptions where organization_id=requested_organization_id and severity='blocking'and status='open'),'latestRun',(select jsonb_build_object('id',run.id,'periodStart',run.period_start,'periodEnd',run.period_end,'payDate',run.pay_date,'status',run.status,'gross',run.total_gross,'deductions',run.total_deductions,'net',run.total_net,'employeeCount',(select count(*)from public.payroll_results where run_id=run.id))from public.payroll_runs run where run.organization_id=requested_organization_id order by run.created_at desc limit 1))into result;return result;end;$$;
create function public.get_payslip(requested_organization_id uuid,requested_payslip_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare actor uuid:=(select auth.uid());payslip_row public.payslips%rowtype;employee_row public.employees%rowtype;begin select*into payslip_row from public.payslips where id=requested_payslip_id and organization_id=requested_organization_id;select*into employee_row from public.employees where id=payslip_row.employee_id and organization_id=requested_organization_id;if actor is null or payslip_row.id is null or not(private.can_business_permission(requested_organization_id,'payroll.read',employee_row.branch_id)or employee_row.membership_id in(select id from public.organization_memberships where organization_id=requested_organization_id and user_id=actor and status='active'))then raise exception'Permission denied.'using errcode='42501';end if;return jsonb_build_object('id',payslip_row.id,'checksum',payslip_row.checksum,'snapshot',payslip_row.snapshot,'createdAt',payslip_row.created_at);end;$$;

alter table public.statutory_rule_sets enable row level security;alter table public.employee_compensation_profiles enable row level security;alter table public.employee_sensitive_identifiers enable row level security;alter table public.payroll_adjustments enable row level security;alter table public.employee_loans enable row level security;alter table public.payroll_runs enable row level security;alter table public.payroll_results enable row level security;alter table public.payroll_components enable row level security;alter table public.payslips enable row level security;alter table public.payroll_exceptions enable row level security;
create policy statutory_rules_read on public.statutory_rule_sets for select to authenticated using(true);create policy compensation_profiles_read on public.employee_compensation_profiles for select to authenticated using(private.payroll_module_enabled(organization_id)and private.can_business_permission(organization_id,'payroll.read',branch_id));create policy payroll_adjustments_read on public.payroll_adjustments for select to authenticated using(private.payroll_module_enabled(organization_id)and private.can_business_permission(organization_id,'payroll.read',null));create policy employee_loans_read on public.employee_loans for select to authenticated using(private.payroll_module_enabled(organization_id)and private.can_business_permission(organization_id,'payroll.read',null));create policy payroll_runs_read on public.payroll_runs for select to authenticated using(private.payroll_module_enabled(organization_id)and private.can_business_permission(organization_id,'payroll.read',branch_id));create policy payroll_results_read on public.payroll_results for select to authenticated using(exists(select 1 from public.payroll_runs run where run.id=payroll_results.run_id and run.organization_id=payroll_results.organization_id and private.can_business_permission(run.organization_id,'payroll.read',run.branch_id)));create policy payroll_components_read on public.payroll_components for select to authenticated using(exists(select 1 from public.payroll_results result join public.payroll_runs run on run.id=result.run_id where result.id=payroll_components.payroll_result_id and result.organization_id=payroll_components.organization_id and private.can_business_permission(run.organization_id,'payroll.read',run.branch_id)));create policy payslips_read on public.payslips for select to authenticated using(exists(select 1 from public.employees employee where employee.id=payslips.employee_id and employee.organization_id=payslips.organization_id and(private.can_business_permission(employee.organization_id,'payroll.read',employee.branch_id)or employee.membership_id in(select membership.id from public.organization_memberships membership where membership.organization_id=employee.organization_id and membership.user_id=(select auth.uid())and membership.status='active'))));create policy payroll_exceptions_read on public.payroll_exceptions for select to authenticated using(private.payroll_module_enabled(organization_id)and private.can_business_permission(organization_id,'payroll.read',null));
revoke all on public.statutory_rule_sets,public.employee_compensation_profiles,public.employee_sensitive_identifiers,public.payroll_adjustments,public.employee_loans,public.payroll_runs,public.payroll_results,public.payroll_components,public.payslips,public.payroll_exceptions from public,anon,authenticated;grant select on public.statutory_rule_sets,public.employee_compensation_profiles,public.payroll_adjustments,public.employee_loans,public.payroll_runs,public.payroll_results,public.payroll_components,public.payslips,public.payroll_exceptions to authenticated;
revoke all on function private.payroll_module_enabled(uuid),private.reject_approved_payroll_mutation(),private.reject_payroll_result_mutation(),private.monthly_withholding(numeric),private.pay_period_divisor(text)from public,anon,authenticated;grant execute on function private.payroll_module_enabled(uuid)to authenticated;
revoke all on function public.save_employee_compensation(uuid,uuid,uuid,date,text,text,numeric,text,numeric,numeric,integer,text,text,text),public.save_employee_sensitive_identifiers(uuid,uuid,text,text,text,text,text,text,text,text,integer),public.masked_employee_identifiers(uuid,uuid),public.calculate_payroll_run(uuid,uuid,date,date,date,text,text,text),public.approve_payroll_run(uuid,uuid),public.payroll_dashboard(uuid),public.get_payslip(uuid,uuid)from public,anon;grant execute on function public.save_employee_compensation(uuid,uuid,uuid,date,text,text,numeric,text,numeric,numeric,integer,text,text,text),public.save_employee_sensitive_identifiers(uuid,uuid,text,text,text,text,text,text,text,text,integer),public.masked_employee_identifiers(uuid,uuid),public.calculate_payroll_run(uuid,uuid,date,date,date,text,text,text),public.approve_payroll_run(uuid,uuid),public.payroll_dashboard(uuid),public.get_payslip(uuid,uuid)to authenticated;
